<?php
require_once __DIR__ . '/auth.php';
$user = require_user($conn);
$videos = $conn->query('SELECT id,upload_video,username,title,description FROM uploaded_videos ORDER BY created_at DESC,id DESC');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WatchWave</title><link rel="stylesheet" href="css/style.css"></head><body><nav class="flex-div"><div class="nav-left flex-div"><img src="images/logo.png" class="logo" alt="WatchWave"></div><div class="nav-right"><a class="btn" href="home.php">Watch</a><a class="btn" href="upload.php">Upload</a><?php if($user['is_admin']): ?><a class="btn" href="admin.php">Moderation</a><?php endif; ?><a class="btn" href="profile.php">Profile</a><a class="btn" href="logout.php">Log out</a></div></nav><main class="video-grid"><?php if(!$videos->num_rows): ?><p>No videos uploaded yet. <a href="upload.php">Upload the first video.</a></p><?php endif; ?><?php while($video=$videos->fetch_assoc()): ?><article class="video-thumbnail"><video controls class="thumbnail-preview"><source src="<?=e($video['upload_video'])?>"></video><div style="padding:0 16px"><h3><?=e($video['title'])?></h3><p class="uploader">Uploaded by <?=e($video['username'])?></p><p><?=e($video['description'])?></p><?php $s=$conn->prepare('SELECT id,username,body FROM comments WHERE video_id=? ORDER BY created_at DESC');$s->bind_param('i',$video['id']);$s->execute();$comments=$s->get_result();while($comment=$comments->fetch_assoc()): ?><p><strong><?=e($comment['username'])?>:</strong> <?=e($comment['body'])?><?php if($user['is_admin']): ?><form method="post" action="delete_comment.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="comment_id" value="<?=$comment['id']?>"><button class="delete-btn" type="submit">Delete comment</button></form><?php endif; ?></p><?php endwhile; ?><form class="comment-form" method="post" action="add_comment.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="video_id" value="<?=$video['id']?>"><input name="body" maxlength="2000" placeholder="Add a comment" required><button class="btn" type="submit">Comment</button></form><?php if($user['is_admin']): ?><form method="post" action="delete_video.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="video_id" value="<?=$video['id']?>"><button class="delete-btn" type="submit">Delete video</button></form><?php endif; ?></div></article><?php endwhile; ?></main></body></html>
